# Corrected scratch-only oracle; original production implementation unchanged.
import unittest
from adapter.planner.codec import json_pointer
from adapter.planner.model import PlannerError
class ScratchCorrected(unittest.TestCase):
 def test_noncanonical_array_index(self):
  with self.assertRaises(PlannerError):json_pointer({"a":[10,20]}, "/a/01")
 def test_literal_escape_and_unicode_key(self):
  self.assertEqual(json_pointer({"~1":"literal"}, "/~01"),"literal")
  self.assertEqual(json_pointer({"é":"unicode"}, "/é"),"unicode")
 def test_unicode_array_index(self):
  with self.assertRaises(PlannerError):json_pointer({"a":[10,20]}, "/a/١")
